import { bust } from '../assetver';
import * as THREE from 'three';
import { register } from '../render/materials';

/**
 * 3D fish built from the species' own Logbook plate (docs/fish_models_study.md).
 *
 * Data: public/fish/models/<slug>.json, generated by scripts/build_fish_models.py from the same
 * generator that draws the plates (art/fish/_tools). Per species it holds the plate's body
 * columns (x, mid, top, bottom, half-width), the median-fin card strip, hinged parts (paired fins,
 * crab claws) and a texture atlas SVG (plate without paddles | paddles | blind-side colour).
 *
 * Mesh (model units: nose→tail tip = 1, nose at +X, origin at the hold point, +Z = plate side):
 *  - tube: elliptical cross-sections through the plate's top/bottom profile, planar-projected
 *    plate texture on both flanks (flatfish/crab: blind patch on the −Z side);
 *  - median card: one alpha-tested strip at z = 0 carrying the dorsal/anal/tail fins pixel-exact;
 *  - parts: paddle fins splayed off the flank on hinges, crab claws on a lift hinge;
 *  - outline: an inflated copy of the tube drawn back-faced in ink (the plates' outline).
 * Two draw calls. Animation is a CPU spine bend (≈2–3k verts) plus part hinges.
 */

interface Part { kind: 'pec' | 'pel' | 'claw'; side?: number; pivot: [number, number]; dir?: [number, number]; quad: [number, number][]; mirror: boolean; splay?: number }
export interface FishModelData {
  slug: string; name: string; plan: string; motion: 'swim' | 'flap' | 'eel' | 'crab'; flat: boolean; zneg: number;
  snout: number; tip: number;
  cols: [number, number, number, number, number][]; // x, mid, top, bot, half-width (plate px)
  card: [number, number, number][]; // x, top, bottom
  parts: Part[]; atlas: string;
}

const ATLAS_W = 512, ATLAS_H = 520, BLIND_V = 516;
const TEX_SCALE = 2; // atlas raster: 1024 × 1040
const RING = 6; // segments per flank (top → bottom)
const LIGHT = new THREE.Vector3(0.25, 0.9, 0.35).normalize();
const INK = 0x2b2622;

/** Built per species once (cached): rest geometry + per-vertex deform data + texture. */
interface Built {
  data: FishModelData;
  /** model-space rest positions (unbent, parts at rest) */
  rest: Float32Array;
  /** part index per vertex (−1 = body/card) and in-plane offsets for parts */
  part: Int16Array;
  pa: Float32Array; // offset along part dir (model units)
  pb: Float32Array; // offset along part normal / claw forward
  pside: Float32Array; // ±1 flank for paired fins
  parts: { kind: Part['kind']; px: number; py: number; pz: number; dx: number; dy: number; nx: number; ny: number; splay: number; side: number }[];
  uv: Float32Array; color: Float32Array;
  outlineRest: Float32Array;
  tex: THREE.Texture;
  /** model-space extents */
  yMin: number; yMax: number; xMin: number; xMax: number; zMax: number;
  /** the 512×256 plate canvas in model units (centre + size), for side-by-side captures */
  plate: { cx: number; cy: number; w: number; h: number };
  /** body depth below the hold point (model units): what rests on the fists */
  belly: number;
}

const cache = new Map<string, Promise<Built | null>>();
const BASE = `${import.meta.env.BASE_URL}fish/models/`;
export const fishSlug = (id: string) => id.replace(/_/g, '-');

export function loadFishModel(slug: string): Promise<Built | null> {
  let p = cache.get(slug);
  if (!p) {
    p = fetch(bust(`${BASE}${slug}.json`))
      .then((r) => (r.ok ? (r.json() as Promise<FishModelData>) : Promise.reject(new Error(String(r.status)))))
      .then(build)
      .catch(() => (slug === 'unknown-fish' ? null : loadFishModel('unknown-fish')));
    cache.set(slug, p);
    // keep a few species (one is on the line at a time); free the evicted atlas on the GPU (≈5.5 MB
    // with mips at 1024×1040 — three.js re-uploads it if a model still shows it)
    if (cache.size > 4) {
      const k = [...cache.keys()].find((c) => c !== slug && c !== 'unknown-fish');
      if (k) { const old = cache.get(k)!; cache.delete(k); void old.then((b) => b?.tex.dispose()); }
    }
  }
  return p;
}

async function rasterise(svg: string): Promise<THREE.Texture> {
  const img = new Image();
  img.src = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  await img.decode();
  const c = document.createElement('canvas');
  c.width = ATLAS_W * TEX_SCALE; c.height = ATLAS_H * TEX_SCALE;
  c.getContext('2d')!.drawImage(img, 0, 0, c.width, c.height);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

async function build(d: FishModelData): Promise<Built> {
  const tex = await rasterise(d.atlas);
  const L = d.tip - d.snout;
  // hold point: 42 % back from the snout (the crab: shell centre), on the body midline
  const hx = d.motion === 'crab' ? (d.snout + d.tip) / 2 : d.snout + 0.42 * L;
  let hy = d.cols[0][1], hbot = 0;
  for (let i = 1; i < d.cols.length; i++) if (d.cols[i][0] >= hx) { hy = d.cols[i][1]; hbot = d.cols[i][3]; break; }
  const X = (x: number) => (hx - x) / L, Y = (y: number) => (hy - y) / L, Z = (z: number) => z / L;

  const pos: number[] = [], uv: number[] = [], col: number[] = [], part: number[] = [], pa: number[] = [], pb: number[] = [], pside: number[] = [];
  const out: number[] = [];
  const tri = (P: number[][], U: number[][], shade = true, pi = -1, A?: number[], B?: number[], S = 0) => {
    // flat per-face shade (very light, the plate already paints back/belly)
    let k = 1;
    if (shade) {
      const ax = P[1][0] - P[0][0], ay = P[1][1] - P[0][1], az = P[1][2] - P[0][2];
      const bx = P[2][0] - P[0][0], by = P[2][1] - P[0][1], bz = P[2][2] - P[0][2];
      const n = new THREE.Vector3(ay * bz - az * by, az * bx - ax * bz, ax * by - ay * bx).normalize();
      k = 0.84 + 0.16 * Math.abs(n.dot(LIGHT));
    }
    for (let j = 0; j < 3; j++) {
      pos.push(P[j][0], P[j][1], P[j][2]); uv.push(U[j][0], U[j][1]); col.push(k, k, k);
      part.push(pi); pa.push(A ? A[j] : 0); pb.push(B ? B[j] : 0); pside.push(S);
    }
  };
  const quad = (a: number[], b: number[], c: number[], e: number[], ua: number[], ub: number[], uc: number[], ue: number[], shade = true) => {
    tri([a, b, c], [ua, ub, uc], shade); tri([a, c, e], [ua, uc, ue], shade);
  };
  const U = (x: number, y: number) => [x / ATLAS_W, 1 - y / ATLAS_H];

  // ---------------------------------------------------------------- tube (+ the outline hull)
  const ring = (c: FishModelData['cols'][number], side: 1 | -1, k: number, grow = 0) => {
    const [x, mid, top, bot, w] = c;
    const th = (Math.PI * k) / RING, ct = Math.cos(th), st = Math.sin(th);
    const h = ct >= 0 ? top : bot;
    const yy = mid - ct * (h + (h > 0 || grow ? grow : 0));
    const ww = (w + (w > 0 || grow ? grow : 0)) * (side < 0 ? d.zneg : 1);
    return { p: [X(x), Y(yy), Z(side * ww * st)], u: side < 0 && d.flat ? U(x, BLIND_V) : U(x, yy) };
  };
  const tube = (grow: number, target: number[] | null) => {
    const cols = d.cols.map((c) => [...c] as typeof c);
    if (grow) { cols[0][0] -= grow; cols[cols.length - 1][0] += grow * 0.5; }
    for (const side of [1, -1] as const) {
      for (let i = 0; i < cols.length - 1; i++) {
        for (let k = 0; k < RING; k++) {
          const a = ring(cols[i], side, k, grow), b = ring(cols[i + 1], side, k, grow), c = ring(cols[i + 1], side, k + 1, grow), e = ring(cols[i], side, k + 1, grow);
          // keep the winding outward on both flanks (outline uses BackSide)
          const q = side > 0 ? [a, e, c, b] : [a, b, c, e];
          if (target) { for (const t of [q[0], q[2], q[1], q[0], q[3], q[2]]) target.push(...t.p); } // hull: inward-wound, drawn BackSide
          else quad(q[0].p, q[1].p, q[2].p, q[3].p, q[0].u, q[1].u, q[2].u, q[3].u);
        }
      }
      // tail-end cap (the peduncle; the tail itself is on the card)
      const last = cols[cols.length - 1];
      if (last[2] + last[3] > 0.5) {
        const cen = { p: [X(last[0]), Y(last[1]), 0], u: U(last[0] - 2, last[1]) };
        for (let k = 0; k < RING; k++) {
          const a = ring(last, side, k, grow), b = ring(last, side, k + 1, grow);
          const q = side > 0 ? [cen, b, a] : [cen, a, b];
          if (target) for (const t of [q[0], q[2], q[1]]) target.push(...t.p);
          else tri(q.map((t) => t.p), q.map((t) => t.u));
        }
      }
    }
  };
  tube(0, null);
  const outlineGrow = 0.0075 * L;
  tube(outlineGrow, out);

  // ---------------------------------------------------------------- median card (z = 0)
  const cd = d.card;
  for (let i = 0; i < cd.length - 1; i++) {
    const [x0, t0, b0] = cd[i], [x1, t1, b1] = cd[i + 1];
    quad([X(x0), Y(t0), 0], [X(x0), Y(b0), 0], [X(x1), Y(b1), 0], [X(x1), Y(t1), 0], U(x0, t0), U(x0, b0), U(x1, b1), U(x1, t1), false);
  }

  // ---------------------------------------------------------------- parts
  const surfaceZ = (x: number, y: number) => {
    let c = d.cols[0];
    for (const cc of d.cols) { if (cc[0] >= x) { c = cc; break; } }
    const [, mid, top, bot, w] = c;
    const h = y < mid ? top : bot;
    if (h <= 0) return 0;
    const v = (y - mid) / h;
    return Math.abs(v) >= 1 ? 0 : w * Math.sqrt(1 - v * v);
  };
  const parts: Built['parts'] = [];
  for (const p of d.parts) {
    const sides = p.mirror ? [1, -1] : [1];
    for (const s of sides) {
      const pi = parts.length;
      const [px, py] = p.pivot;
      const dx = p.dir ? p.dir[0] : 0, dy = p.dir ? p.dir[1] : -1;
      const nx = -dy, ny = dx;
      const zs = p.kind === 'claw' ? 0 : s * (surfaceZ(px, py) * (s < 0 ? d.zneg : 1) + 0.8);
      parts.push({ kind: p.kind, px: X(px), py: Y(py), pz: Z(zs), dx: -dx, dy: -dy, nx: -nx, ny: -ny, splay: ((p.splay ?? 0) * Math.PI) / 180, side: p.kind === 'claw' ? p.side ?? 1 : s });
      const corner = (q: [number, number]) => {
        const rx = q[0] - px, ry = q[1] - py;
        const a = (rx * dx + ry * dy) / L, b = (rx * nx + ry * ny) / L;
        return { p: [X(q[0]), Y(q[1]), Z(zs)], u: U(q[0], q[1] + 256), a, b };
      };
      const c = p.quad.map(corner);
      const order = s > 0 ? [0, 1, 2, 0, 2, 3] : [0, 2, 1, 0, 3, 2];
      for (let t = 0; t < 6; t += 3) {
        const v = [c[order[t]], c[order[t + 1]], c[order[t + 2]]];
        tri(v.map((q) => q.p), v.map((q) => q.u), false, pi, v.map((q) => q.a), v.map((q) => q.b), s);
      }
    }
  }

  const rest = new Float32Array(pos);
  let yMin = Infinity, yMax = -Infinity, xMin = Infinity, xMax = -Infinity, zMax = 0;
  for (let i = 0; i < rest.length; i += 3) {
    xMin = Math.min(xMin, rest[i]); xMax = Math.max(xMax, rest[i]);
    yMin = Math.min(yMin, rest[i + 1]); yMax = Math.max(yMax, rest[i + 1]);
    zMax = Math.max(zMax, Math.abs(rest[i + 2]));
  }
  return {
    data: d, rest, part: new Int16Array(part), pa: new Float32Array(pa), pb: new Float32Array(pb), pside: new Float32Array(pside), parts,
    uv: new Float32Array(uv), color: new Float32Array(col), outlineRest: new Float32Array(out), tex, yMin, yMax, xMin, xMax, zMax,
    plate: { cx: X(256), cy: Y(128), w: 512 / L, h: 256 / L },
    belly: hbot / L,
  };
}

/** Readability boost for tiny fish (real length in m → drawn length in m). ≥ 0.35 m: true size. */
export function shownLength(m: number) {
  const k = Math.min(1, Math.max(0, (0.35 - m) / 0.25));
  return m * (1 + 0.5 * k);
}

const SPINE = 40;

export class FishModel {
  /** positioned/rotated by fishing.ts; scale = drawn length (m) */
  group = new THREE.Group();
  /** inner frame: flatfish/crab lie on their blind side; `present` turns them toward the camera */
  private orient = new THREE.Group();
  private mat: THREE.MeshBasicMaterial;
  private inkMat = new THREE.MeshBasicMaterial({ color: INK, side: THREE.BackSide });
  private mesh: THREE.Mesh;
  private outline: THREE.Mesh;
  private b: Built | null = null;
  private want = '';
  private t = 0;
  /** tail wag amplitude (rad), decays toward `wagBase` */
  wag = 0.3;
  wagBase = 0.15;
  wagHz = 3.2;
  /** 0..1 leap/thrash pose (a strong C-arch + fast tail) */
  leap = 0;
  /** 0 = natural (flatfish/crab lie flat), 1 = plate side squarely toward the viewer (+Z) */
  present = 0;
  private curl = 0; private curlV = 0; private curlSign = 1;
  private spineX = new Float32Array(SPINE + 1);
  private spineP = new Float32Array((SPINE + 1) * 2);
  private spineA = new Float32Array(SPINE + 1);
  /** current species data (null while loading) */
  get data() { return this.b?.data ?? null; }
  /** model-space bounds (nose→tail = 1 unit) of the loaded model */
  get bounds() { return this.b ? { xMin: this.b.xMin, xMax: this.b.xMax, yMin: this.b.yMin, yMax: this.b.yMax, zMax: this.b.zMax, belly: this.b.belly } : null; }
  get ready() { return !!this.b; }
  get plateFrame() { return this.b?.plate ?? null; }
  get triangles() { return this.b ? (this.b.rest.length + this.b.outlineRest.length) / 9 : 0; }
  /** freeze/advance the animation clock (captures) */
  setTime(t: number) { this.t = t; }
  get isFlat() { return !!this.b?.data.flat; }

  /** tinted: follow the time-of-day tint like the scenery (false for the studio captures) */
  constructor(tinted = true) {
    this.mat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide, alphaTest: 0.5 });
    if (tinted) register(this.mat);
    this.mesh = new THREE.Mesh(new THREE.BufferGeometry(), this.mat);
    this.outline = new THREE.Mesh(new THREE.BufferGeometry(), this.inkMat);
    this.orient.add(this.outline, this.mesh);
    this.group.add(this.orient);
    this.group.visible = false;
    for (const m of [this.mesh, this.outline]) { m.frustumCulled = false; m.renderOrder = 4; }
  }

  /** Load (or reuse) the model for a species id; resolves when it is shown. */
  setSpecies(id: string): Promise<void> {
    const slug = fishSlug(id);
    this.want = slug;
    return loadFishModel(slug).then((b) => { if (b && this.want === slug) this.use(b); });
  }

  /** Real length in metres (with the tiny-fish readability boost). */
  setLength(m: number) { this.group.scale.setScalar(shownLength(m)); }

  private use(b: Built) {
    if (this.b === b) return;
    this.b = b;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(b.rest.slice(), 3).setUsage(THREE.DynamicDrawUsage));
    g.setAttribute('uv', new THREE.BufferAttribute(b.uv, 2));
    g.setAttribute('color', new THREE.BufferAttribute(b.color, 3));
    this.mesh.geometry.dispose();
    this.mesh.geometry = g;
    const og = new THREE.BufferGeometry();
    og.setAttribute('position', new THREE.BufferAttribute(b.outlineRest.slice(), 3).setUsage(THREE.DynamicDrawUsage));
    this.outline.geometry.dispose();
    this.outline.geometry = og;
    this.mat.map = b.tex;
    this.mat.needsUpdate = true;
    this.deform();
  }

  /** kick the tail (flop) */
  flop(a = 0.6) {
    this.wag = Math.max(this.wag, a);
    this.curlSign = -this.curlSign;
    this.curlV += this.curlSign * a * 9;
  }

  update(dt: number) {
    this.t += dt;
    this.wag += (this.wagBase - this.wag) * Math.min(1, dt * 1.5);
    // curl spring (the flop: a C-bend that snaps over and settles)
    this.curlV += (-60 * this.curl - 7 * this.curlV) * dt;
    this.curl += this.curlV * dt;
    const k = this.present;
    if (this.b?.data.flat) this.orient.rotation.set(-Math.PI / 2 * (1 - k), 0, 0);
    else this.orient.rotation.set(0, 0, 0);
    this.deform();
  }

  /** spine angle along the body: s = 0 at the hold point, + toward the nose */
  private bendAngle(X: number, motion: FishModelData['motion']) {
    const tw = this.t * Math.PI * 2;
    const s = 0.42 - X; // 0 nose → 1 tail tip
    const curl = this.curl + this.leap * 1.2 * Math.sin(this.t * 7);
    if (motion === 'crab') return 0;
    if (motion === 'eel') {
      const A = 0.35 + this.wag * 0.6 + this.leap * 0.4;
      return (curl * 1.8) * X + A * (0.35 + 0.65 * s) * Math.sin(tw * this.wagHz * 0.55 - Math.PI * 2 * 1.1 * s);
    }
    if (motion === 'flap') {
      const A = 0.2 + this.wag * 0.55 + this.leap * 0.3;
      return curl * 0.8 * X + A * (0.45 + 0.55 * s) * Math.sin(tw * this.wagHz * 0.6 - Math.PI * 2 * 0.7 * s);
    }
    const ramp = Math.pow(Math.min(1, Math.max(0, (s - 0.3) / 0.7)), 1.4);
    const A = this.wag * 1.1 + this.leap * 0.5;
    return curl * X + A * ramp * Math.sin(tw * (this.wagHz + this.leap * 3) - Math.PI * 2 * 0.6 * s);
  }

  private deform() {
    const b = this.b;
    if (!b) return;
    const m = b.data.motion;
    // spine: angle φ(X) and position P(X) (x,z), integrated outward from the hold point (fixed)
    const x0 = b.xMin - 0.02, x1 = b.xMax + 0.02, dx = (x1 - x0) / SPINE;
    for (let i = 0; i <= SPINE; i++) { const X = x0 + i * dx; this.spineX[i] = X; this.spineA[i] = this.bendAngle(X, m) - this.bendAngle(0, m); }
    let i0 = Math.round((0 - x0) / dx); i0 = Math.max(0, Math.min(SPINE, i0));
    const P = this.spineP;
    P[i0 * 2] = this.spineX[i0]; P[i0 * 2 + 1] = 0;
    for (let i = i0 + 1; i <= SPINE; i++) { const a = (this.spineA[i] + this.spineA[i - 1]) / 2; P[i * 2] = P[(i - 1) * 2] + Math.cos(a) * dx; P[i * 2 + 1] = P[(i - 1) * 2 + 1] + Math.sin(a) * dx; }
    for (let i = i0 - 1; i >= 0; i--) { const a = (this.spineA[i] + this.spineA[i + 1]) / 2; P[i * 2] = P[(i + 1) * 2] - Math.cos(a) * dx; P[i * 2 + 1] = P[(i + 1) * 2 + 1] - Math.sin(a) * dx; }
    // flop arch: head and tail lift off the hands (U), strongest at the snap of the curl spring
    const arch = m === 'crab' ? 0 : Math.min(0.9, Math.abs(this.curl) * 0.45 + this.leap * 0.25);
    const bend = (X: number, Y: number, Zv: number, o: Float32Array, j: number) => {
      let f = (X - x0) / dx; f = Math.max(0, Math.min(SPINE - 1e-4, f));
      const i = Math.floor(f), u = f - i;
      const px = P[i * 2] + (P[i * 2 + 2] - P[i * 2]) * u, pz = P[i * 2 + 1] + (P[i * 2 + 3] - P[i * 2 + 1]) * u;
      const a = this.spineA[i] + (this.spineA[i + 1] - this.spineA[i]) * u;
      const c = Math.cos(a), s = Math.sin(a);
      o[j] = px - Zv * s; o[j + 1] = Y + arch * X * X; o[j + 2] = pz + Zv * c;
    };
    // parts: hinge angles
    const tw = this.t;
    const ang = b.parts.map((p, k) => {
      if (p.kind === 'claw') return 0.35 + 0.3 * Math.sin(tw * 3.4 + p.side * 1.3) + Math.abs(this.curl) * 0.4 + this.wag * 0.25;
      const flapA = p.kind === 'pec' ? 0.22 : 0.1;
      return p.splay + flapA * Math.sin(tw * 5.5 + k) * (0.4 + this.wag);
    });
    const pa = this.mesh.geometry.getAttribute('position') as THREE.BufferAttribute;
    const arr = pa.array as Float32Array, rest = b.rest;
    for (let v = 0, n = rest.length / 3; v < n; v++) {
      const j = v * 3, pi = b.part[v];
      if (pi < 0) { bend(rest[j], rest[j + 1], rest[j + 2], arr, j); continue; }
      const p = b.parts[pi], a = b.pa[v], bb = b.pb[v], q = ang[pi];
      if (p.kind === 'claw') {
        // lift about the shell's left-right axis (the claw rises toward +Z, the shell top)
        const fy = (rest[j + 1] - p.py), fx = rest[j] - p.px;
        bend(p.px + fx, p.py + fy * Math.cos(q), p.pz + fy * Math.sin(q), arr, j);
      } else {
        const c = Math.cos(q), s = Math.sin(q);
        const X = p.px + bb * p.nx + a * c * p.dx, Y = p.py + bb * p.ny + a * c * p.dy, Zv = p.pz + a * s * p.side;
        bend(X, Y, Zv, arr, j);
      }
    }
    pa.needsUpdate = true;
    const oa = this.outline.geometry.getAttribute('position') as THREE.BufferAttribute;
    const oarr = oa.array as Float32Array, orr = b.outlineRest;
    for (let j = 0; j < orr.length; j += 3) bend(orr[j], orr[j + 1], orr[j + 2], oarr, j);
    oa.needsUpdate = true;
  }
}
